import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Easing, Img } from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type SpotlightOverlayProps = Record<string, any>;

const SpotlightOverlay: React.FC<SpotlightOverlayProps> = ({
  backgroundColor = "#000000",
  transparentBackground = false,
  durationInSeconds = 5,
  backgroundImage = "https://malloy-files-c0ddahgefecthmcs.z03.azurefd.net/web/template_assets/images/newspaper.jpeg",
  spotlightRadius = 250,
  spotlightFeather = 100,
  overlayOpacity = 0.85,
  startX = 300,
  startY = 540,
  endX = 1620,
  endY = 540,
  easeType = "ease-in-out",
}) => {
  useFontLoader(["Inter"]); // Basic loader logic maintained
  
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Easing Map
  const easingMap = {
    "linear": Easing.linear,
    "ease-in": Easing.in(Easing.quad),
    "ease-out": Easing.out(Easing.quad),
    "ease-in-out": Easing.inOut(Easing.quad),
  };
  const activeEasing = easingMap[easeType] || Easing.linear;

  // Calculate Movement
  const progress = interpolate(frame, [0, durationInSeconds * fps], [0, 1], {
    extrapolateRight: "clamp",
    easing: activeEasing,
  });

  // Calculate Current Position
  const currentX = interpolate(progress, [0, 1], [startX, endX]);
  const currentY = interpolate(progress, [0, 1], [startY, endY]);

  // Construct Gradient Mask
  // The mask needs to be transparent in the center (to show the image) 
  // and dark overlay color on the outside.
  // CSS Syntax: radial-gradient(circle at X Y, transparent start, color end)
  
  const innerStop = spotlightRadius;
  const outerStop = spotlightRadius + spotlightFeather;
  
  // Ensure we handle Hex colors with opacity correctly
  // We use rgba for the overlay color to control opacity simply
  const overlayColor = `rgba(0, 0, 0, ${overlayOpacity})`; 
  
  const backgroundStyle: React.CSSProperties = {
    backgroundColor: transparentBackground ? "transparent" : backgroundColor,
  };

  return (
    <AbsoluteFill style={backgroundStyle}>
      {/* 1. Base Layer: The Image */}
      <AbsoluteFill>
        <Img 
          src={backgroundImage} 
          style={{
            width: "100%",
            height: "100%",
            objectFit: "cover",
          }}
        />
      </AbsoluteFill>

      {/* 2. Overlay Layer: The Gradient Mask */}
      {/* This layer sits on top. It is transparent at the spotlight position 
          and transitions to the dark overlay color outside. */}
      <AbsoluteFill
        style={{
          background: `radial-gradient(circle at ${currentX}px ${currentY}px, transparent ${innerStop}px, ${overlayColor} ${outerStop}px)`,
          transition: "none", // Critical for frame-based animation
        }}
      />
    </AbsoluteFill>
  );
};

export default SpotlightOverlay;